const input = $('Input').item.json;
const text = String(input.text ?? '').trim();
const command = text.toLocaleLowerCase('pt-BR').replace(/[.!?]+$/g, '').trim();
const stageAliases = {
  inicio: 'start',
  nome: 'name',
  contato: 'contact',
};
const reviewFieldAliases = {
  nome: 'name',
  contato: 'contact',
  telefone: 'contact',
  email: 'contact',
  'e-mail': 'contact',
  objetivo: 'objective',
  escolaridade: 'education',
  curso: 'courses',
  cursos: 'courses',
  habilidade: 'skills',
  habilidades: 'skills',
  experiencia: 'experiences',
  experiencias: 'experiences',
  experiência: 'experiences',
  experiências: 'experiences',
};
const reviewFieldLabels = {
  name: 'nome',
  contact: 'contato',
  objective: 'objetivo',
  experiences: 'experiência profissional',
  education: 'escolaridade',
  courses: 'cursos',
  skills: 'habilidades',
};
const optionalReviewFields = new Set([
  'objective',
  'experiences',
  'education',
  'courses',
  'skills',
]);

let stage = stageAliases[$json.stage] ?? $json.stage ?? 'start';
const draft = { ...($json.draft ?? {}) };

if (draft.nome && !draft.name) {
  draft.name = draft.nome;
}
delete draft.nome;

function normalizeBrazilianPhone(value) {
  let digits = value.replace(/\D/g, '');

  if ((digits.length === 12 || digits.length === 13) && digits.startsWith('55')) {
    digits = digits.slice(2);
  }

  if (![10, 11].includes(digits.length)) {
    return null;
  }

  if (digits.startsWith('0') || /^(\d)\1+$/.test(digits)) {
    return null;
  }

  return '+55' + digits;
}

function isValidEmail(value) {
  return value.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value);
}

function isValidExperience(value) {
  return value.length >= 5 && value.length <= 1000;
}

function isValidField(value, maximum) {
  return value.length >= 2 && value.length <= maximum;
}

function isSkipCommand(value) {
  return value === 'pular' || value === 'não tenho' || value === 'nao tenho';
}

function formatContact(value) {
  if (!value) {
    return 'não informado';
  }

  return value.value ?? value.normalized ?? 'não informado';
}

function formatList(value) {
  if (!Array.isArray(value) || value.length === 0) {
    return 'não informado';
  }

  return value
    .map(item => typeof item === 'string' ? item : item.description ?? '')
    .filter(Boolean)
    .join('; ') || 'não informado';
}

function formatExperiences() {
  if (draft.first_job === true && (!Array.isArray(draft.experiences) || draft.experiences.length === 0)) {
    return 'primeiro emprego';
  }

  return formatList(draft.experiences);
}

function buildReviewSummary() {
  const lines = [
    'Confira seus dados:',
    'Nome: ' + (draft.name || 'não informado'),
    'Contato: ' + formatContact(draft.contact),
    'Objetivo: ' + (draft.objective || 'não informado'),
    'Experiência: ' + formatExperiences(),
    'Escolaridade: ' + (draft.education || 'não informado'),
    'Cursos: ' + formatList(draft.courses),
    'Habilidades: ' + formatList(draft.skills),
  ];

  return lines.join('\n') + '\n\nResponda "confirmar" se estiver tudo certo ou "corrigir <campo>" para alterar um dado.';
}

function isDraftCommand(value) {
  return [
    'gerar',
    'redigir',
    'gerar currículo',
    'gerar curriculo',
    'criar currículo',
    'criar curriculo',
  ].includes(value);
}

function buildResumeDraft() {
  const lines = [
    (draft.name || 'Nome não informado').toLocaleUpperCase('pt-BR'),
    'Contato: ' + formatContact(draft.contact),
    '',
    'OBJETIVO',
    draft.objective || 'Não informado',
    '',
    'EXPERIÊNCIA',
    formatExperiences(),
    '',
    'ESCOLARIDADE',
    draft.education || 'Não informado',
    '',
    'CURSOS',
    formatList(draft.courses),
    '',
    'HABILIDADES',
    formatList(draft.skills),
  ];

  return lines.join('\n');
}

function buildDraftReply() {
  return 'Rascunho atual (modelo determinístico, sem inventar informações):\n\n' +
    draft.generated_resume.text +
    '\n\nResponda "aprovar" para continuar ou "corrigir <campo>" para voltar à revisão.';
}

function generateDraft() {
  const resumeText = buildResumeDraft();

  draft.generated_resume = {
    status: 'preview',
    method: 'deterministic_template_v1',
    text: resumeText,
  };
  stage = 'draft_ready';

  return 'Rascunho gerado (modelo determinístico, sem inventar informações):\n\n' +
    resumeText +
    '\n\nResponda "aprovar" para continuar ou "corrigir <campo>" para voltar à revisão.';
}

function isPdfCommand(value) {
  return [
    'pdf',
    'gerar pdf',
    'gerar currículo em pdf',
    'gerar curriculo em pdf',
    'criar pdf',
  ].includes(value);
}

function isPdfRetrievalCommand(value) {
  return [
    'baixar pdf',
    'download pdf',
    'baixar currículo',
    'baixar curriculo',
  ].includes(value);
}

function requestPdfRetrieval() {
  if (draft.pdf_status !== 'stored' || !draft.pdf_artifact_id) {
    return 'Ainda não há um PDF armazenado. Responda "gerar PDF" para criar o arquivo.';
  }

  pdfRetrievalRequested = true;
  pdfArtifactId = draft.pdf_artifact_id;
  pdfStoragePath = draft.pdf_storage_path ?? 'db://resume_artifacts/' + draft.pdf_artifact_id;
  return 'PDF localizado. Preparando o download do arquivo.';
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;',
  }[character]));
}

function buildPdfFilename() {
  const baseName = (draft.name || 'curriculo')
    .toLocaleLowerCase('pt-BR')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'curriculo';

  return baseName + '.pdf';
}

function buildPdfArtifactId(filename) {
  const senderSegment = String(input.sender_id || 'sender')
    .toLocaleLowerCase('pt-BR')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'sender';
  const messageSegment = String(input.message_id || Date.now())
    .toLocaleLowerCase('pt-BR')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || String(Date.now());
  const filenameSegment = String(filename)
    .toLocaleLowerCase('pt-BR')
    .replace(/[^a-z0-9.-]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'curriculo.pdf';

  return senderSegment + '-' + messageSegment + '-' + filenameSegment;
}

function buildPdfHtml() {
  const resumeText = draft.generated_resume?.text ?? buildResumeDraft();
  const escapedText = escapeHtml(resumeText);

  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">' +
    '<style>body{font-family:Arial,sans-serif;color:#222;margin:48px}pre{font-family:Arial,sans-serif;white-space:pre-wrap;line-height:1.45;font-size:12pt}</style>' +
    '</head><body><pre>' + escapedText + '</pre></body></html>';
}

function requestPdf() {
  const html = buildPdfHtml();
  const filename = buildPdfFilename();
  const artifactId = buildPdfArtifactId(filename);
  const storagePath = 'db://resume_artifacts/' + artifactId;

  pdfRequested = true;
  pdfHtml = html;
  pdfHtmlBinary = {
    data: Buffer.from(html, 'utf8').toString('base64'),
    mimeType: 'text/html',
    fileName: 'index.html',
    fileExtension: 'html',
  };
  pdfFilename = filename;
  pdfArtifactId = artifactId;
  pdfStoragePath = storagePath;
  draft.pdf_status = 'requested';
  draft.pdf_filename = filename;
  draft.pdf_artifact_id = artifactId;
  draft.pdf_storage_path = storagePath;
  stage = 'pdf_requested';

  return 'PDF solicitado. A conversão usa o Gotenberg local e será entregue como arquivo.';
}

function askEducation() {
  stage = 'education';
  return 'Qual é sua escolaridade? Você pode informar se está estudando ou responder "pular".';
}

function askCourses() {
  stage = 'courses';
  return 'Você fez algum curso? Informe o nome ou responda "pular".';
}

function askSkills() {
  stage = 'skills';
  return 'Quais habilidades você quer destacar? Liste-as ou responda "pular".';
}

function askReview() {
  stage = 'review_data';
  return buildReviewSummary();
}

function finishCollection() {
  delete draft.review_status;
  delete draft.pending_review_field;
  return askReview();
}

const experiences = Array.isArray(draft.experiences) ? [...draft.experiences] : [];
if (Array.isArray(draft.experiencias) && experiences.length === 0) {
  experiences.push(...draft.experiencias);
}
delete draft.experiencias;

function addExperience(description) {
  experiences.push({
    id: 'exp-' + (experiences.length + 1),
    description,
  });
  draft.experiences = experiences;
  delete draft.first_job;
}

function parseReviewField(value) {
  const match = value.match(/^(?:corrigir|editar|alterar)\s+(.+)$/);

  if (!match) {
    return null;
  }

  return reviewFieldAliases[match[1].trim()] ?? null;
}

function askCorrection(field) {
  const optionalHint = optionalReviewFields.has(field) ? ' Responda "pular" para remover esse campo.' : '';
  stage = 'review_edit';
  return 'Qual é o novo valor de ' + reviewFieldLabels[field] + '?' + optionalHint;
}

function completeReviewEdit() {
  delete draft.pending_review_field;
  delete draft.review_status;
  return askReview();
}

function applyReviewEdit(field) {
  if (isSkipCommand(command)) {
    if (optionalReviewFields.has(field)) {
      if (field === 'experiences') {
        draft.experiences = [];
        draft.first_job = true;
      } else {
        delete draft[field];
      }
      return null;
    }

    return 'Esse campo é obrigatório. Envie um valor válido para ' + reviewFieldLabels[field] + '.';
  }

  if (field === 'name') {
    if (!isValidField(text, 120)) {
      return 'Envie um nome com até 120 caracteres.';
    }

    draft.name = text;
    return null;
  }

  if (field === 'contact') {
    const normalizedPhone = normalizeBrazilianPhone(text);

    if (isValidEmail(text)) {
      draft.contact = {
        type: 'email',
        value: text,
        normalized: text.toLocaleLowerCase('pt-BR'),
      };
      return null;
    }

    if (normalizedPhone) {
      draft.contact = {
        type: 'phone',
        value: text,
        normalized: normalizedPhone,
      };
      return null;
    }

    return 'Não reconheci esse contato. Envie um telefone com DDD ou um e-mail válido.';
  }

  if (field === 'objective' || field === 'education') {
    const maximum = field === 'objective' ? 160 : 160;

    if (!isValidField(text, maximum)) {
      return 'Envie ' + reviewFieldLabels[field] + ' com até ' + maximum + ' caracteres.';
    }

    draft[field] = text;
    return null;
  }

  if (field === 'courses' || field === 'skills') {
    if (!isValidField(text, 300)) {
      return 'Envie ' + reviewFieldLabels[field] + ' com até 300 caracteres.';
    }

    draft[field] = [text];
    return null;
  }

  if (field === 'experiences') {
    if (!isValidExperience(text)) {
      return 'Envie uma experiência com pelo menos 5 caracteres e até 1000 caracteres.';
    }

    draft.experiences = [{
      id: 'exp-1',
      description: text,
    }];
    delete draft.first_job;
    return null;
  }

  return 'Não reconheci o campo para correção.';
}

let pdfRequested = false;
let pdfHtml = null;
let pdfHtmlBinary = null;
let pdfFilename = null;
let pdfArtifactId = null;
let pdfStoragePath = null;
let pdfRetrievalRequested = false;

let reply = 'Responda com seu nome para continuar.';

if (stage === 'start') {
  stage = 'name';
  reply = 'Oi! Qual nome deve aparecer no currículo?';
} else if (stage === 'name') {
  if (text.length > 0 && text.length <= 120) {
    draft.name = text;
    stage = 'contact';
    reply = 'Qual telefone ou e-mail você quer colocar no currículo?';
  } else {
    reply = 'Envie um nome com até 120 caracteres para continuar.';
  }
} else if (stage === 'contact') {
  const normalizedPhone = normalizeBrazilianPhone(text);

  if (isValidEmail(text)) {
    draft.contact = {
      type: 'email',
      value: text,
      normalized: text.toLocaleLowerCase('pt-BR'),
    };
    stage = 'objective';
    reply = 'Que tipo de trabalho você procura? Se preferir, responda "pular".';
  } else if (normalizedPhone) {
    draft.contact = {
      type: 'phone',
      value: text,
      normalized: normalizedPhone,
    };
    stage = 'objective';
    reply = 'Que tipo de trabalho você procura? Se preferir, responda "pular".';
  } else {
    reply = 'Não reconheci esse contato. Envie um telefone com DDD ou um e-mail válido.';
  }
} else if (stage === 'objective') {
  if (command === 'pular') {
    delete draft.objective;
    stage = 'experience';
    reply = 'Você já trabalhou, fez algum bico ou ajudou em um negócio da família? Conte o que fazia ou responda "primeiro emprego".';
  } else if (isValidField(text, 160)) {
    draft.objective = text;
    stage = 'experience';
    reply = 'Você já trabalhou, fez algum bico ou ajudou em um negócio da família? Conte o que fazia ou responda "primeiro emprego".';
  } else {
    reply = 'Descreva o objetivo em até 160 caracteres ou responda "pular".';
  }
} else if (stage === 'experience') {
  if (command === 'primeiro emprego' || command === 'pular') {
    draft.experiences = experiences;
    draft.first_job = true;
    reply = askEducation();
  } else if (isValidExperience(text)) {
    addExperience(text);
    stage = 'experience_more';
    reply = 'Quer adicionar outra experiência? Responda "sim" ou "não".';
  } else {
    reply = 'Conte uma experiência com pelo menos 5 caracteres, ou responda "primeiro emprego".';
  }
} else if (stage === 'experience_more') {
  if (command === 'sim' || command === 'adicionar' || command === 'adicionar outra') {
    stage = 'experience_additional';
    reply = 'Conte outra experiência: o que você fazia?';
  } else if (command === 'não' || command === 'nao' || command === 'pular') {
    reply = askEducation();
  } else {
    reply = 'Responda "sim" para adicionar outra experiência ou "não" para continuar.';
  }
} else if (stage === 'experience_additional') {
  if (command === 'não' || command === 'nao' || command === 'pular') {
    reply = askEducation();
  } else if (isValidExperience(text)) {
    addExperience(text);
    stage = 'experience_more';
    reply = 'Quer adicionar outra experiência? Responda "sim" ou "não".';
  } else {
    reply = 'Conte uma experiência com pelo menos 5 caracteres, ou responda "não" para continuar.';
  }
} else if (stage === 'education') {
  if (isSkipCommand(command)) {
    delete draft.education;
    reply = askCourses();
  } else if (isValidField(text, 160)) {
    draft.education = text;
    reply = askCourses();
  } else {
    reply = 'Informe sua escolaridade em até 160 caracteres ou responda "pular".';
  }
} else if (stage === 'courses') {
  if (isSkipCommand(command)) {
    delete draft.courses;
    reply = askSkills();
  } else if (isValidField(text, 300)) {
    draft.courses = [text];
    reply = askSkills();
  } else {
    reply = 'Informe o curso em até 300 caracteres ou responda "pular".';
  }
} else if (stage === 'skills') {
  if (isSkipCommand(command)) {
    delete draft.skills;
    reply = finishCollection();
  } else if (isValidField(text, 300)) {
    draft.skills = [text];
    reply = finishCollection();
  } else {
    reply = 'Informe suas habilidades em até 300 caracteres ou responda "pular".';
  }
} else if (stage === 'review_data') {
  const requestedField = parseReviewField(command);

  if (command === 'confirmar' || command === 'confirmado' || command === 'sim' || command === 'ok') {
    draft.review_status = 'confirmed';
    delete draft.pending_review_field;
    stage = 'ready_for_drafting';
    reply = 'Dados confirmados. O currículo está pronto para a próxima etapa de redação.';
  } else if (requestedField) {
    delete draft.review_status;
    draft.pending_review_field = requestedField;
    reply = askCorrection(requestedField);
  } else {
    reply = buildReviewSummary();
  }
} else if (stage === 'review_edit') {
  const pendingField = draft.pending_review_field;

  if (!pendingField) {
    reply = askReview();
  } else if (command === 'cancelar' || command === 'voltar') {
    delete draft.pending_review_field;
    reply = askReview();
  } else {
    const editError = applyReviewEdit(pendingField);

    if (editError) {
      reply = editError;
    } else {
      reply = completeReviewEdit();
    }
  }
} else if (stage === 'ready_for_drafting') {
  const requestedField = parseReviewField(command);

  if (requestedField) {
    delete draft.review_status;
    draft.pending_review_field = requestedField;
    reply = askCorrection(requestedField);
  } else if (isDraftCommand(command)) {
    reply = generateDraft();
  } else {
    reply = 'Dados confirmados. Responda "gerar currículo" para criar o rascunho.';
  }
} else if (stage === 'draft_ready') {
  const requestedField = parseReviewField(command);

  if (command === 'aprovar' || command === 'aprovado' || command === 'confirmar') {
    draft.generated_resume.status = 'approved';
    stage = 'draft_approved';
    reply = 'Rascunho aprovado. Ele está pronto para a próxima etapa de PDF.';
  } else if (requestedField) {
    delete draft.generated_resume;
    delete draft.review_status;
    draft.pending_review_field = requestedField;
    reply = askCorrection(requestedField);
  } else if (isDraftCommand(command)) {
    reply = generateDraft();
  } else {
    reply = buildDraftReply();
  }
} else if (stage === 'draft_approved') {
  const requestedField = parseReviewField(command);

  if (isPdfRetrievalCommand(command)) {
    reply = requestPdfRetrieval();
  } else if (isPdfCommand(command)) {
    reply = requestPdf();
  } else if (requestedField) {
    delete draft.generated_resume;
    delete draft.review_status;
    draft.pending_review_field = requestedField;
    reply = askCorrection(requestedField);
  } else {
    reply = 'Rascunho aprovado. Responda "gerar PDF" para solicitar o arquivo.';
  }
} else if (stage === 'pdf_requested') {
  if (isPdfRetrievalCommand(command)) {
    reply = requestPdfRetrieval();
  } else if (isPdfCommand(command)) {
    reply = requestPdf();
  } else {
    reply = 'O PDF já foi solicitado. Aguarde a conversão pelo Gotenberg local.';
  }
} else {
  reply = 'Não consegui identificar a etapa atual. Tente novamente.';
}

const output = {
  json: {
    sender_id: input.sender_id,
    stage,
    draft,
    revision: $json.revision,
    reply,
    pdf_requested: pdfRequested,
    pdf_html: pdfHtml,
    pdf_filename: pdfFilename,
    pdf_artifact_id: pdfArtifactId,
    pdf_storage_path: pdfStoragePath,
    pdf_retrieval_requested: pdfRetrievalRequested,
  },
};

if (pdfHtmlBinary) {
  output.binary = {
    pdf_html_file: pdfHtmlBinary,
  };
}

return output;

const input = $input.item.json;
const draft = { ...(input.draft ?? {}) };
const binary = $input.item.binary?.data;
const storagePath = draft.pdf_storage_path;

if (!storagePath || !binary) {
  throw new Error('PDF binário ou identificador de armazenamento ausente.');
}

const pdfBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const pdfBase64 = pdfBuffer.toString('base64');
const sizeBytes = pdfBuffer.length;

draft.pdf_status = 'stored';
draft.pdf_mime_type = binary.mimeType ?? 'application/pdf';
draft.pdf_size_bytes = sizeBytes;
draft.pdf_stored_at = new Date().toISOString();

return {
  json: {
    ...input,
    draft,
    pdf_base64: pdfBase64,
    reply: 'PDF armazenado no PostgreSQL local como ' + storagePath + '.',
  },
  binary: $input.item.binary,
};

const input = $input.item.json;
const artifactId = input.artifact_id ?? input.requested_artifact_id;

if (!input.artifact_id || !input.content_base64) {
  return {
    json: {
      sender_id: input.sender_id,
      pdf_artifact_id: artifactId,
      pdf_found: false,
      reply: 'Não encontrei um PDF armazenado para esta sessão.',
    },
  };
}

const fileName = input.file_name || 'curriculo.pdf';
const fileExtension = fileName.split('.').pop() || 'pdf';
const sizeBytes = Number(input.size_bytes ?? 0);

return {
  json: {
    sender_id: input.sender_id,
    pdf_artifact_id: input.artifact_id,
    pdf_filename: fileName,
    pdf_mime_type: input.mime_type || 'application/pdf',
    pdf_size_bytes: Number.isFinite(sizeBytes) ? sizeBytes : null,
    pdf_found: true,
    reply: 'PDF recuperado do armazenamento local.',
  },
  binary: {
    data: {
      data: input.content_base64,
      mimeType: input.mime_type || 'application/pdf',
      fileName,
      fileExtension,
      fileSize: Number.isFinite(sizeBytes) ? String(sizeBytes) : undefined,
    },
  },
};

const raw = $input.item.json;
const grant = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const statusCode = Number(raw.statusCode ?? grant.status_code ?? 500);
const senderId = String(grant.sender_id ?? raw.sender_id ?? '');
const artifactId = String(grant.artifact_id ?? raw.artifact_id ?? '');

if (statusCode !== 201 || grant.grant_created !== true) {
  return {
    json: {
      sender_id: senderId,
      stage: 'pdf_requested',
      draft: {
        pdf_status: 'stored',
        pdf_artifact_id: artifactId || null,
      },
      delivery_status: 'failed',
      artifact_id: artifactId || null,
      grant_id: null,
      grant_expires_at: null,
      download_endpoint_path: '/webhook/curriculo-pdf-dev',
      status_code: statusCode,
      reply: 'PDF foi armazenado, mas a concessão temporária não pôde ser criada.',
    },
  };
}

return {
  json: {
    sender_id: senderId,
    stage: 'pdf_requested',
    draft: {
      pdf_status: 'stored',
      pdf_artifact_id: artifactId,
    },
    delivery_status: 'ready',
    artifact_id: artifactId,
    grant_id: grant.grant_id,
    grant_expires_at: grant.expires_at,
    download_endpoint_path: '/webhook/curriculo-pdf-dev',
    status_code: 201,
    reply: 'PDF pronto para entrega. Concessão temporária criada.',
  },
};
